import 'package:territory_game/model/player.dart';
import 'package:territory_game/model/quiz_models/question_models/question.dart';
import "package:intl/intl.dart";
import 'package:territory_game/model/quiz_models/quiz_type.dart';

/// A class for storing the event history and question history of a single game.
class History {
  // A player-non-specific history of questions generated by the chatbot for ensuring quiz content variance.
  Map<QuizType, List<String>> questionHistory;
  // A history of the events and chat posts that have occurred in a game.
  List<String> activityHistory;

  History({
    Map<QuizType, List<String>>? questionHistory,
    List<String>? activityHistory,
  }) : questionHistory =
           questionHistory ??
           {
             QuizType.multipleChoice: [],
             QuizType.codingProblem: [],
             QuizType.codingExercise: [],
             QuizType.theory: [],
           },
       activityHistory = activityHistory ?? [];

  /// Loads a History from a JSON object.
  factory History.fromJson(Map<String, dynamic> json) {
    Map<QuizType, List<String>> questionHistory = {};
    for (String type in json["questionHistory"].keys) {
      questionHistory[QuizType.fromString(type)] = List<String>.from(
        json["questionHistory"][type],
      );
    }

    final activityHistory = List<String>.from(json["activityHistory"]);

    return History(
      questionHistory: questionHistory,
      activityHistory: activityHistory,
    );
  }

  /// Converts the History object to a JSON-friendly Map.
  Map<String, dynamic> toJson() {
    Map<String, dynamic> serializedQuestionHistory = {};
    for (QuizType type in questionHistory.keys) {
      serializedQuestionHistory[type.name] = questionHistory[type];
    }
    return {
      "questionHistory": serializedQuestionHistory,
      "activityHistory": activityHistory,
    };
  }

  // Adds a set of questions to the question history as strings.
  void addQuestions(QuizType questionType, List<Question> questions) {
    for (Question question in questions) {
      questionHistory[questionType]?.add(question.question);
    }
  }

  // Adds a chat message to the activity history.
  void addChatMessage(Player author, String message) {
    final currentTime = DateFormat.jm().format(DateTime.now());
    final post = "$currentTime: ${author.displayName}: $message";
    activityHistory.add(post);
  }

  // Add an event to the activity history.
  void addEvent(String event) {
    final currentTime = DateFormat.jm().format(DateTime.now());
    final post = "$currentTime: $event";
    activityHistory.add(post);
  }
}
